#nullable enable

using Campaigns.Contracts;
using Campaigns.Views;
using Marten;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Generated from the model's GIVEN/THEN cells, NOT from the implementation — which is the only reason
/// these tests mean anything. Pattern: view. Status: ready. Owned by backend-agent.
///
/// A GIVEN/THEN HAS NO WHEN, AND THAT IS CORRECT. A read model only ever reads events that already exist,
/// so no command can be the WHEN — <em>Understanding EventSourcing</em> ch. 3: "you typically do not use
/// GWTs but GTs (Given - Then)". Each test appends the GIVEN straight to the stream (history, not requests
/// to replay) and then asserts the DATA in the read model: which rows, and with which values.
///
/// RECIPE UNDER SPECIFICATION: a self-aggregating snapshot registered <c>Inline</c>
/// (<c>Projections.Snapshot&lt;MessageStatus&gt;</c>). Inline is what makes a THEN assertable the moment the
/// append returns — nothing here waits. Contrast <see cref="CampaignDashboardTests"/>, whose view is Async
/// and where every assertion is preceded by a wait.
///
/// These GTs say nothing about the recipe, and could not: <c>Event(s) → View</c> is satisfied by a live
/// fold, a snapshot, a flat table or a rollup. They pin down the FOLD. What the recipe COSTS is measured in
/// <see cref="ProjectionRecipeTests"/>, and the two suites are deliberately different questions — swap this
/// view to a live aggregation (delete one registration line, read with
/// <c>AggregateStreamAsync&lt;MessageStatus&gt;</c>) and every assertion below still has to hold.
/// </summary>
public sealed class MessageStatusTests(AppFixture fixture) : IntegrationContext(fixture)
{
    /// <summary>
    /// A second fixed Message stream key. SeedData holds the values a GIVEN shares across slices; a value
    /// only this slice's GTs need lives here, the same way QueueMessageTests owns its SenderId.
    /// </summary>
    private static readonly Guid SecondMessageId = Guid.Parse("77777777-7777-7777-7777-777777777777");

    private static string[] TwoRecipients => ["a@example.com", "b@example.com"];

    /// <summary>
    /// The GIVEN, in one place. A Message stream is keyed by messageId, so the stream key IS the view's
    /// <c>identity=</c> — which is what makes this view a single-stream fold in the first place.
    /// </summary>
    private Task Queued(Guid messageId, params string[] recipients) =>
        Given(messageId, new MessageQueued(
            messageId, SeedData.CampaignId, QueueMessageTests.SenderId, "January newsletter",
            recipients, SeedData.SeededAt));

    private async Task<MessageStatus?> Row(Guid messageId)
    {
        await using var session = Store.QuerySession();
        return await session.LoadAsync<MessageStatus>(messageId);
    }

    // a queued message starts with nothing delivered
    //   GIVEN MessageQueued
    //   THEN  MessageStatus
    [Fact]
    public async Task AQueuedMessageStartsWithNothingDelivered()
    {
        var messageId = SeedData.MessageId;
        await Queued(messageId, TwoRecipients);

        var row = await Row(messageId);

        row.ShouldNotBeNull();

        // The row's id is the view's identity=, and here that is also the stream id.
        row.Id.ShouldBe(messageId);
        row.MessageId.ShouldBe(messageId);

        // Carried, not computed: the event supplies both, so the model states them as plain fields.
        row.CampaignId.ShouldBe(SeedData.CampaignId);
        row.Subject.ShouldBe("January newsletter");

        // derived="recipientCount=recipients" — a COUNT of the array, which is why the model cannot state
        // it as a rename: mappings="recipientCount=recipients" would claim a string[] IS an int.
        row.RecipientCount.ShouldBe(2);

        // The point of this GT. "Starts with nothing delivered" is a claim about the ABSENCE of events, and
        // a projection that seeded a counter from the recipient list would still pass every other test here.
        row.Delivered.ShouldBe(0);
        row.Bounced.ShouldBe(0);
        row.Status.ShouldBe(MessageStatus.Queued);
    }

    // a delivery and a bounce are counted separately
    //   GIVEN MessageQueued, MessageDelivered, MessageBounced
    //   THEN  MessageStatus
    [Fact]
    public async Task ADeliveryAndABounceAreCountedSeparately()
    {
        var messageId = SeedData.MessageId;
        await Queued(messageId, TwoRecipients);
        await Given(messageId,
            new MessageDelivered(messageId, "a@example.com", SeedData.SeededAt),
            new MessageBounced(messageId, "b@example.com", "mailbox full", SeedData.SeededAt));

        var row = await Row(messageId);

        row.ShouldNotBeNull();

        // TWO OUTCOME EVENTS LAND ON ONE ROW AND MUST NOT BE CONFLATED. Asserting the two counters
        // SEPARATELY is the whole content of this GT: a fold that bumped the same field for both events
        // would report Delivered == 2 / Bounced == 0 and pass any test that only ever sent one of them,
        // and "2 of 2 recipients accounted for" would still be true.
        row.Delivered.ShouldBe(1);
        row.Bounced.ShouldBe(1);
        row.RecipientCount.ShouldBe(2);
    }

    // status is derived from the counts and not carried
    //   GIVEN MessageQueued, MessageDelivered
    //   THEN  MessageStatus
    [Fact]
    public async Task StatusIsDerivedFromTheCountsAndNotCarried()
    {
        // TWO STREAMS WITH THE SAME EVENT TYPES IN THE SAME ORDER, differing only in how many recipients
        // the queue event carried. That is what makes "derived" executable: no MessageDelivered anywhere
        // carries a status, and the C# record could not — so if the two rows disagree, the value can only
        // be a function of the accumulated counts.
        var settled = SeedData.MessageId;
        var outstanding = SecondMessageId;

        await Queued(settled, "only@example.com");
        await Given(settled, new MessageDelivered(settled, "only@example.com", SeedData.SeededAt));

        await Queued(outstanding, TwoRecipients);
        await Given(outstanding, new MessageDelivered(outstanding, "a@example.com", SeedData.SeededAt));

        var one = await Row(settled);
        var two = await Row(outstanding);

        one.ShouldNotBeNull();
        two.ShouldNotBeNull();

        // Same events, same Delivered count. Different status.
        one.Delivered.ShouldBe(1);
        two.Delivered.ShouldBe(1);

        one.RecipientCount.ShouldBe(1);
        one.Status.ShouldBe(MessageStatus.Complete);      // every recipient has an outcome

        two.RecipientCount.ShouldBe(2);
        two.Status.ShouldBe(MessageStatus.Queued);        // one still outstanding

        // And it is a function of the WHOLE stream, not of the last event: the last event applied to both
        // streams is the same MessageDelivered.
        (await EventsFor(settled)).Last().ShouldBeOfType<MessageDelivered>();
        (await EventsFor(outstanding)).Last().ShouldBeOfType<MessageDelivered>();
    }
}
